#include "stdlib/blas/base/strsv.h"
#include "stdlib/blas/base/strsv_cblas.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/min_view_buffer_index.h"
#include "stdlib/ndarray/base/min_view_buffer_index.h"

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param order    storage layout
* @param uplo     specifies whether `A` is an upper or lower triangular matrix
* @param trans    specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag     specifies whether `A` has a unit diagonal
* @param N        number of elements along each dimension of `A`
* @param A        input matrix
* @param LDA      stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param x        input vector
* @param strideX  `x` stride length
* @return         output value
*/
float API_SUFFIX(c_strsv)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const float *A, const CBLAS_INT LDA, float *X, const CBLAS_INT strideX ) {
	CBLAS_INT sx = strideX;
	if ( sx < 0 ) {
		sx = -sx;
	}
	return API_SUFFIX(cblas_strsv)( order, uplo, trans, diag, N, A, LDA, X, sx );
}

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` using alternative indexing semantics, where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA2  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param x         input vector
* @param strideX   `x` stride length
* @param offsetX   starting index for `x`
* @return          output value
*/
float API_SUFFIX(c_strsv_ndarray)( const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const float *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT sx = strideX;
	if ( sx < 0 ) {
		sx = -sx;
	}
	X += stdlib_strided_min_view_buffer_index( N, strideX, offsetX ); // adjust array pointer
	const int64_t shape[] = { N, N };
	const int64_t strides[] = { strideA1, strideA2 };
	A += stdlib_ndarray_min_view_buffer_index( 2, shape, strides, offsetA ); // adjust array pointer
	return API_SUFFIX(cblas_strsv)( order, uplo, trans, diag, N, A, LDA, X, sx );
}
